                            routes[a] = ra[:ia] + ra[ia + 1:]
                            routes[b] = rb[:p] + [c] + rb[p:]
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break

        routes = [r for r in routes if r]

    final = []
    used = set()
    for r in routes:
        nr = []
        for x in r:
            if x != depot and x not in used:
                used.add(x)
                nr.append(x)
        if nr:
            final.append(nr)

    for c in ids:
        if c not in used:
            final.append([c])

    return final
